// ============================================================
// OTF Export — DottFont Generator
//
// Builds and downloads a .otf font file containing all characters
// defined in dinish-bold-metrics.json, using opentype.js.
//
// Each glyph is generated by running the full dot-generation pipeline
// (renderTextMask + drawMeshGradientPreview) on a single character,
// then mapping canvas dot positions to font coordinate space.
//
// Font metrics (UPM, ascender, descender) and per-glyph advance widths
// are read from dinish-bold-metrics.json. BASELINE_Y is still measured
// from the canvas at runtime to match the browser's actual rendering.
//
// Coordinate mapping:
//   fontX = (canvasX - PADDING) * SCALE
//   fontY = (BASELINE_Y - canvasY) * SCALE
//
// Path union:
//   All dot shapes within a glyph are first approximated as polygons,
//   then merged into a single outline via Clipper.js boolean union.
//   This eliminates overlapping contours, reducing file size and
//   producing cleaner results in design tools (equivalent to
//   Inkscape's Path > Union).
//
// Depends on globals from script-generator_DottFont.js:
//   presenceStrength, sizeMultiplier, tailleGenerationMultiplier,
//   currentShape, DOT_SPACING, PADDING, FONT_SIZE, MAX_RADIUS, MIN_RADIUS,
//   gCtx, renderTextMask, drawMeshGradientPreview, generate
// ============================================================

const exportOtfBtn = document.getElementById('export-otf-btn');

// Scaling factor for Clipper integer coordinates.
// Clipper requires integer inputs; multiplying by this factor preserves
// sub-unit precision before rounding, then we divide back when building the Path.
const CLIPPER_SCALE = 100;

// Returns a CCW polygon (array of Clipper {X,Y} points) approximating a circle.
// n=32 gives sub-pixel error at all normal font sizes.
// CCW winding in Y-up font coordinates = positive area = included by NonZero fill rule.
function getCirclePolygon(cx, cy, r, n = 16) {
  const pts = [];
  for (let i = 0; i < n; i++) {
    const a = (2 * Math.PI * i) / n;
    pts.push({
      X: Math.round((cx + Math.cos(a) * r) * CLIPPER_SCALE),
      Y: Math.round((cy + Math.sin(a) * r) * CLIPPER_SCALE)
    });
  }
  return pts;
}

// Returns a CCW polygon for an axis-aligned square.
// halfSize is half the side length.
// Vertex order TL → BL → BR → TR gives CCW winding in Y-up font coordinates.
function getSquarePolygon(cx, cy, halfSize) {
  const s = halfSize;
  return [
    { X: Math.round((cx - s) * CLIPPER_SCALE), Y: Math.round((cy + s) * CLIPPER_SCALE) },
    { X: Math.round((cx - s) * CLIPPER_SCALE), Y: Math.round((cy - s) * CLIPPER_SCALE) },
    { X: Math.round((cx + s) * CLIPPER_SCALE), Y: Math.round((cy - s) * CLIPPER_SCALE) },
    { X: Math.round((cx + s) * CLIPPER_SCALE), Y: Math.round((cy + s) * CLIPPER_SCALE) },
  ];
}

// Returns a CCW polygon approximating an ellipse.
// rx, ry: semi-axes. Same winding logic as getCirclePolygon.
function getEllipsePolygon(cx, cy, rx, ry, n = 16) {
  const pts = [];
  for (let i = 0; i < n; i++) {
    const a = (2 * Math.PI * i) / n;
    pts.push({
      X: Math.round((cx + Math.cos(a) * rx) * CLIPPER_SCALE),
      Y: Math.round((cy + Math.sin(a) * ry) * CLIPPER_SCALE)
    });
  }
  return pts;
}

// Returns a CCW polygon approximating a horizontal pill (stadium) shape.
// halfW: half total width, halfH: half height (= corner radius).
// n: segments per semicircle. Traversal: right semicircle (-π/2 → +π/2)
// then left semicircle (+π/2 → +3π/2), both CCW in Y-up.
function getTraitPolygon(cx, cy, halfW, halfH, n = 16) {
  const pts = [];
  const rx = halfW - halfH; // distance from center to each semicircle center
  // Right semicircle
  for (let i = 0; i <= n; i++) {
    const a = -Math.PI / 2 + (Math.PI * i) / n;
    pts.push({
      X: Math.round((cx + rx + Math.cos(a) * halfH) * CLIPPER_SCALE),
      Y: Math.round((cy + Math.sin(a) * halfH) * CLIPPER_SCALE)
    });
  }
  // Left semicircle
  for (let i = 0; i <= n; i++) {
    const a = Math.PI / 2 + (Math.PI * i) / n;
    pts.push({
      X: Math.round((cx - rx + Math.cos(a) * halfH) * CLIPPER_SCALE),
      Y: Math.round((cy + Math.sin(a) * halfH) * CLIPPER_SCALE)
    });
  }
  return pts;
}

// Returns [outerPolygon, innerPolygon] for a ring (donut) shape.
// outer is CCW (solid area, winding +1), inner is CW (hole, winding -1).
// With NonZero fill rule, overlapping outer+inner regions cancel to 0 → hole.
// If another solid shape overlaps the hole, the hole is filled (correct union behavior).
function getCircleOutlinePolygons(cx, cy, outerR, innerR, n = 16) {
  const outer = [];
  const inner = [];
  for (let i = 0; i < n; i++) {
    const aOuter = (2 * Math.PI * i) / n;       // CCW: increasing angle
    const aInner = (2 * Math.PI * (n - i)) / n; // CW: decreasing angle (reversed)
    outer.push({
      X: Math.round((cx + Math.cos(aOuter) * outerR) * CLIPPER_SCALE),
      Y: Math.round((cy + Math.sin(aOuter) * outerR) * CLIPPER_SCALE)
    });
    inner.push({
      X: Math.round((cx + Math.cos(aInner) * innerR) * CLIPPER_SCALE),
      Y: Math.round((cy + Math.sin(aInner) * innerR) * CLIPPER_SCALE)
    });
  }
  return [outer, inner];
}

// Cubic Bezier circle approximation constant: (4/3) × tan(π/8) ≈ 0.5523.
// Each of 4 quadrant segments has < 0.03% radial error — indistinguishable from a true circle.
const BEZIER_K = 0.5522847498;

// Appends a circle to an opentype.Path using 4 cubic Bezier segments.
// CCW winding (cw=false) = solid area; CW (cw=true) = hole (for circle_outline inner ring).
function addCircleBezier(path, cx, cy, r, cw) {
  const k = BEZIER_K * r;
  if (!cw) {
    // CCW: right → top → left → bottom → right
    path.moveTo(cx + r, cy);
    path.bezierCurveTo(cx + r, cy + k,   cx + k, cy + r,   cx,     cy + r);
    path.bezierCurveTo(cx - k, cy + r,   cx - r, cy + k,   cx - r, cy    );
    path.bezierCurveTo(cx - r, cy - k,   cx - k, cy - r,   cx,     cy - r);
    path.bezierCurveTo(cx + k, cy - r,   cx + r, cy - k,   cx + r, cy    );
  } else {
    // CW: right → bottom → left → top → right (hole in NonZero fill)
    path.moveTo(cx + r, cy);
    path.bezierCurveTo(cx + r, cy - k,   cx + k, cy - r,   cx,     cy - r);
    path.bezierCurveTo(cx - k, cy - r,   cx - r, cy - k,   cx - r, cy    );
    path.bezierCurveTo(cx - r, cy + k,   cx - k, cy + r,   cx,     cy + r);
    path.bezierCurveTo(cx + k, cy + r,   cx + r, cy + k,   cx + r, cy    );
  }
  path.close();
}

// Appends an ellipse (rx × ry semi-axes) to an opentype.Path, CCW.
function addEllipseBezier(path, cx, cy, rx, ry) {
  const kx = BEZIER_K * rx;
  const ky = BEZIER_K * ry;
  path.moveTo(cx + rx, cy);
  path.bezierCurveTo(cx + rx, cy + ky,   cx + kx, cy + ry,   cx,      cy + ry);
  path.bezierCurveTo(cx - kx, cy + ry,   cx - rx, cy + ky,   cx - rx, cy     );
  path.bezierCurveTo(cx - rx, cy - ky,   cx - kx, cy - ry,   cx,      cy - ry);
  path.bezierCurveTo(cx + kx, cy - ry,   cx + rx, cy - ky,   cx + rx, cy     );
  path.close();
}

// Appends a horizontal pill (stadium) to an opentype.Path, CCW.
// halfW: half total width, halfH: half height = corner radius.
function addTraitBezier(path, cx, cy, halfW, halfH) {
  const rx = halfW - halfH;  // distance from center to each semicircle center
  const k  = BEZIER_K * halfH;
  path.moveTo(cx + rx + halfH, cy);
  // Right semicircle: rightmost → top
  path.bezierCurveTo(cx + rx + halfH, cy + k,   cx + rx + k, cy + halfH,   cx + rx, cy + halfH);
  // Top straight edge
  path.lineTo(cx - rx, cy + halfH);
  // Left semicircle: top → leftmost → bottom
  path.bezierCurveTo(cx - rx - k, cy + halfH,   cx - rx - halfH, cy + k,   cx - rx - halfH, cy);
  path.bezierCurveTo(cx - rx - halfH, cy - k,   cx - rx - k, cy - halfH,   cx - rx, cy - halfH);
  // Bottom straight edge
  path.lineTo(cx + rx, cy - halfH);
  // Right semicircle: bottom → rightmost
  path.bezierCurveTo(cx + rx + k, cy - halfH,   cx + rx + halfH, cy - k,   cx + rx + halfH, cy);
  path.close();
}

// Dispatches to the correct Bezier function for the current shape.
// Used when dots cannot overlap (no Clipper union needed).
function addShapeBezierToPath(path, cx, cy, r) {
  if (currentShape === 'square') {
    // Square has straight edges — 4 lineTo segments, no Bezier needed
    path.moveTo(cx - r, cy + r);
    path.lineTo(cx - r, cy - r);
    path.lineTo(cx + r, cy - r);
    path.lineTo(cx + r, cy + r);
    path.close();
  } else if (currentShape === 'ellipse') {
    addEllipseBezier(path, cx, cy, r * (2 / 2.75), r);
  } else if (currentShape === 'trait') {
    addTraitBezier(path, cx, cy, r, r * (1.7 / 3.614));
  } else if (currentShape === 'circle_outline') {
    addCircleBezier(path, cx, cy, r,                    false);  // outer CCW
    addCircleBezier(path, cx, cy, r * (0.758 / 1.157),  true);   // inner CW = hole
  } else {
    addCircleBezier(path, cx, cy, r, false);
  }
}

// Loads Clipper.js from CDN into the page if not already present.
// Injected dynamically so index.html does not need to be modified.
async function loadClipper() {
  if (window.ClipperLib) return;
  await new Promise((resolve, reject) => {
    const s = document.createElement('script');
    s.src = 'https://cdn.jsdelivr.net/npm/clipper-lib@6.4.2/clipper.js';
    s.onload = resolve;
    s.onerror = reject;
    document.head.appendChild(s);
  });
}

// Merges an array of Clipper polygons into a single unified outline.
// Uses NonZero fill rule: any region with non-zero winding is filled.
// CCW shapes contribute +1, CW holes contribute -1 — overlaps cancel correctly.
// Returns a ClipperLib.Paths array (array of {X,Y} point arrays).
function unionPolygons(polygons) {
  if (polygons.length === 0) return [];
  const cpr = new ClipperLib.Clipper();
  cpr.AddPaths(polygons, ClipperLib.PolyType.ptSubject, true);
  const solution = new ClipperLib.Paths();
  cpr.Execute(
    ClipperLib.ClipType.ctUnion,
    solution,
    ClipperLib.PolyFillType.pftNonZero,
    ClipperLib.PolyFillType.pftNonZero
  );
  return solution;
}

// Converts a Clipper Paths result to an opentype.js Path.
// Each polygon in the Clipper result becomes a closed subpath.
// Divides coordinates by CLIPPER_SCALE to recover font units.
function clipperToOpentypePath(clipperPaths) {
  const path = new opentype.Path();
  for (const poly of clipperPaths) {
    if (poly.length === 0) continue;
    path.moveTo(poly[0].X / CLIPPER_SCALE, poly[0].Y / CLIPPER_SCALE);
    for (let i = 1; i < poly.length; i++) {
      path.lineTo(poly[i].X / CLIPPER_SCALE, poly[i].Y / CLIPPER_SCALE);
    }
    path.close();
  }
  return path;
}

// Builds and downloads an OTF font for all characters defined in
// dinish-bold-metrics.json. Font metrics and advance widths come from
// the JSON; BASELINE_Y is measured from the canvas at runtime.
// All dot shapes within each glyph are merged via boolean union before export.
async function exportOTF() {
  exportOtfBtn.textContent = 'En cours...';
  exportOtfBtn.disabled = true;

  // Load Clipper.js for polygon boolean union (injected dynamically, no HTML change needed).
  try {
    await loadClipper();
  } catch (e) {
    console.error('Failed to load Clipper.js:', e);
    exportOtfBtn.textContent = 'Erreur Clipper';
    exportOtfBtn.disabled = false;
    return;
  }

  // Load font metrics and glyph data from JSON.
  // Provides UPM, ascender, descender, and per-glyph advance widths.
  let metrics;
  try {
    const res = await fetch('source_export_otf/dinish-bold-metrics.json');
    metrics = await res.json();
  } catch (e) {
    console.error('Failed to load dinish-bold-metrics.json:', e);
    exportOtfBtn.textContent = 'Erreur JSON';
    exportOtfBtn.disabled = false;
    return;
  }

  const UPM       = metrics.units.upm;
  const ASCENDER  = metrics.fontMetrics.ascender;
  const DESCENDER = metrics.fontMetrics.descender;

  // Measure the alphabetic baseline position in canvas pixels.
  // Strategy: measure 'A' with textBaseline='top' (same as renderTextMask) and use
  // actualBoundingBoxDescent. Since 'A' has yMin=0 (sits exactly on the alphabetic
  // baseline), actualBoundingBoxDescent = distance from the 'top' reference point
  // down to the baseline. This value is always positive and consistent across browsers.
  //
  // Why not fontBoundingBoxAscent? Returns the font-wide ascender (≈1050/1024*px),
  // which is larger than the actual 'top'-to-baseline distance → glyphs shift +211u.
  // Why not alphabeticBaseline? The Canvas spec uses upward-positive convention, so
  // alphabeticBaseline with textBaseline='top' returns a negative number in Chrome/FF
  // → BASELINE_Y = PADDING + negative = too small → glyphs shift into negative y.
  // ctx is the global hidden-canvas context defined in script-generator_DottFont.js
  ctx.font         = `700 ${FONT_SIZE}px DINish, sans-serif`;
  ctx.textBaseline = 'top';
  const measured   = ctx.measureText('A');
  const BASELINE_Y = PADDING + measured.actualBoundingBoxDescent;
  const SCALE      = UPM / FONT_SIZE;  // canvas px → font units

  // Charset is driven by the JSON — only characters with defined metrics are exported.
  const CHARSET = Object.keys(metrics.glyphs);

  // PostScript glyph names must be ASCII-only identifiers (Adobe Glyph List).
  // Using a Unicode character as a PS name (e.g. 'É' instead of 'Eacute') produces
  // an invalid post table that Windows rejects — even though FontLab accepts it.
  const GLYPH_NAMES = {
    // Digits
    '0':'zero',        '1':'one',         '2':'two',        '3':'three',     '4':'four',
    '5':'five',        '6':'six',         '7':'seven',      '8':'eight',     '9':'nine',
    // Punctuation and symbols
    '.':'period',      '?':'question',    ':':'colon',      ',':'comma',      ';':'semicolon',
    '!':'exclam',      '#':'numbersign',  '$':'dollar',     '%':'percent',   '&':'ampersand',
    "'": 'quotesingle','(':'parenleft',   ')':'parenright', '+':'plus',      '*':'asterisk',
    '-':'hyphen',      '_':'underscore',  '/':'slash',      '\\':'backslash','ß':'germandbls',
    '@':'at',          '<':'less',        '>':'greater',    '"':'quotedbl',
    // Accented uppercase — required for valid PS names (Windows rejects non-ASCII names)
    'À':'Agrave',      'Á':'Aacute',      'Â':'Acircumflex','Ã':'Atilde',
    'Ä':'Adieresis',   'Å':'Aring',       'Ç':'Ccedilla',   'È':'Egrave',
    'É':'Eacute',      'Ê':'Ecircumflex', 'Ë':'Edieresis',  'Ì':'Igrave',
    'Í':'Iacute',      'Î':'Icircumflex', 'Ï':'Idieresis',  'Ñ':'Ntilde',
    'Ò':'Ograve',      'Ó':'Oacute',      'Ô':'Ocircumflex','Õ':'Otilde',
    'Ö':'Odieresis',   'Ù':'Ugrave',      'Ú':'Uacute',     'Û':'Ucircumflex',
    'Ü':'Udieresis',   'Ÿ':'Ydieresis',
    // Accented lowercase
    'à':'agrave',      'á':'aacute',      'â':'acircumflex','ã':'atilde',
    'ä':'adieresis',   'å':'aring',       'ç':'ccedilla',   'è':'egrave',
    'é':'eacute',      'ê':'ecircumflex', 'ë':'edieresis',  'ì':'igrave',
    'í':'iacute',      'î':'icircumflex', 'ï':'idieresis',  'ñ':'ntilde',
    'ò':'ograve',      'ó':'oacute',      'ô':'ocircumflex','õ':'otilde',
    'ö':'odieresis',   'ù':'ugrave',      'ú':'uacute',     'û':'ucircumflex',
    'ü':'udieresis',   'ÿ':'ydieresis',
  };

  const glyphs = [];

  // .notdef — required as the first glyph in any valid OTF
  glyphs.push(new opentype.Glyph({
    name: '.notdef', unicode: 0, advanceWidth: 500, path: new opentype.Path()
  }));

  // space — gives kerning/layout tools a working word-break glyph
  glyphs.push(new opentype.Glyph({
    name: 'space', unicode: 32, advanceWidth: 222, path: new opentype.Path()
  }));

  // Disable blur during export: renderTextMask creates a full blur canvas when
  // outsetRadius > 0, but the contour zone is not exported in OTF — wasted work.
  const savedOutsetRadius = outsetRadius;
  outsetRadius = 0;

  // Hoist constants that are identical for every glyph
  const step       = DOT_SPACING * tailleGenerationMultiplier;
  const canOverlap = 2 * MAX_RADIUS * sizeMultiplier > DOT_SPACING;

  // Pre-compute radius formula parts: radius = radiusBase + darkness * radiusRange
  // Avoids repeating the same multiplications for every dot of every glyph.
  const radiusMul   = sizeMultiplier * tailleGenerationMultiplier;
  const radiusBase  = MIN_RADIUS * radiusMul;
  const radiusRange = (MAX_RADIUS - MIN_RADIUS) * radiusMul;

  // One glyph per character present in the JSON
  for (let gi = 0; gi < CHARSET.length; gi++) {
    const char = CHARSET[gi];

    // Yield to the browser every 10 glyphs: allows repaints and prevents
    // the "page unresponsive" dialog on large charsets.
    if (gi % 10 === 0) {
      exportOtfBtn.textContent = `${gi} / ${CHARSET.length}`;
      await new Promise(r => setTimeout(r, 0));
    }

    // Run the full render pipeline for this single character
    const { canvasW, canvasH } = renderTextMask(char);

    // When meshSize=0 the gradient is uniformly black on text — identical to the text
    // mask itself. Read ctx directly and skip drawMeshGradientPreview entirely,
    // saving per-pixel gradient computation + two canvas reads for every glyph.
    let pixels;
    if (meshSize === 0) {
      pixels = ctx.getImageData(0, 0, canvasW, canvasH).data;
    } else {
      // Pass canvasH as refWidth so the gradient x-axis uses a fixed reference (FONT_SIZE + 2*PADDING)
      // identical for every character, eliminating per-character gradient remapping and trembling.
      drawMeshGradientPreview(canvasW, canvasH, canvasH);
      pixels = gCtx.getImageData(0, 0, canvasW, canvasH).data;
    }

    const polygons   = canOverlap ? [] : null;
    const directPath = canOverlap ? null : new opentype.Path();

    for (let y = step / 2; y < canvasH; y += step) {
      for (let x = step / 2; x < canvasW; x += step) {
        const i          = (Math.floor(y) * canvasW + Math.floor(x)) * 4;
        const brightness = (pixels[i] + pixels[i+1] + pixels[i+2]) / 3;
        if (brightness >= 245) continue;

        // Apply the same probabilistic filter as the SVG output.
        // meshSize 0 → solid black, brightness always 0 → use flat probability instead
        const probability = meshSize === 0
          ? 1 - presenceStrength
          : Math.max(0, 1 - (brightness / 204) * presenceStrength * 2);
        if (Math.random() > probability) continue;

        const darkness = Math.max(0, 1 - brightness / 204);
        const radius   = radiusBase + darkness * radiusRange;

        // Map canvas px → font units, flipping Y axis.
        // Round cx/cy to integers to avoid float-to-int rounding drift in opentype.js:
        // a non-integer step (e.g. 4.8px → 32.77 font units) would otherwise cause
        // alternating 32/33-unit gaps, producing visible trembling in the exported OTF.
        const fx = Math.round((x - PADDING) * SCALE);
        const fy = Math.round((BASELINE_Y - y) * SCALE);
        const fr = radius * SCALE;

        if (canOverlap) {
          // Polygon mode — will be merged by Clipper union below
          if (currentShape === 'square') {
            polygons.push(getSquarePolygon(fx, fy, fr));
          } else if (currentShape === 'ellipse') {
            polygons.push(getEllipsePolygon(fx, fy, fr * (2 / 2.75), fr));
          } else if (currentShape === 'trait') {
            polygons.push(getTraitPolygon(fx, fy, fr, fr * (1.7 / 3.614)));
          } else if (currentShape === 'circle_outline') {
            const [outer, inner] = getCircleOutlinePolygons(fx, fy, fr, fr * (0.758 / 1.157));
            polygons.push(outer, inner);
          } else {
            polygons.push(getCirclePolygon(fx, fy, fr));
          }
        } else {
          // Direct Bezier mode — 4 cubic segments per shape, no Clipper
          addShapeBezierToPath(directPath, fx, fy, fr);
        }
      }
    }

    const path = canOverlap
      ? clipperToOpentypePath(unionPolygons(polygons))
      : directPath;

    const name = GLYPH_NAMES[char] || char;
    glyphs.push(new opentype.Glyph({
      name,
      unicode:      char.codePointAt(0),
      advanceWidth: metrics.glyphs[char].advanceWidth,
      path
    }));
  }

  // Restore blur radius now that all glyphs are processed
  outsetRadius = savedOutsetRadius;

  const font = new opentype.Font({
    familyName:     'FLUTGRABEN',
    styleName:      'Regular',
    unitsPerEm:     UPM,
    ascender:       ASCENDER,
    descender:      DESCENDER,
    copyright:      '© 2026 Zoé Berthelot',
    manufacturer:   'Flutgraben e.V.',
    designer:       'Zoé Berthelot @Neutronzoo',
    version:        'Version 1.000',
    description:    `Generated with DottFont Generator — ${currentShape} / mesh:${meshSize} / taille:${tailleGenerationMultiplier.toFixed(2)} / size:${sizeMultiplier.toFixed(2)} / presence:${presenceStrength.toFixed(2)}`,
    license:        'This Font Software is licensed under the SIL Open Font License, Version 1.1.',
    licenseURL:     'https://scripts.sil.org/OFL',
    glyphs
  });

  // Build filename from current settings: shape_mesh_tailleGeneration_size_presence
  const filename = `FLUTGRABEN_${currentShape}_${meshSize}_${tailleGenerationMultiplier.toFixed(2)}_${sizeMultiplier.toFixed(2)}_${presenceStrength.toFixed(2)}.otf`;
  font.download(filename);

  // Restore the display to the current text input after processing
  generate();
  exportOtfBtn.textContent = 'OTF';
  exportOtfBtn.disabled = false;
}

// OTF export button — builds the font on click
exportOtfBtn.addEventListener('click', exportOTF);